"use server";

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

export type AuthFormState = { error?: string; message?: string; email?: string };

export async function authenticate(_prev: AuthFormState, formData: FormData): Promise<AuthFormState> {
  const intent = formData.get("intent") === "signup" ? "signup" : "signin";
  const email = String(formData.get("email") ?? "").trim();
  const password = String(formData.get("password") ?? "");

  if (!email || !password) return { error: "Enter your email and password.", email };

  const supabase = await createClient();

  if (intent === "signin") {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) return { error: "Incorrect email or password.", email };
  } else {
    if (password.length < 8) return { error: "Use a password of at least 8 characters.", email };
    const { data, error } = await supabase.auth.signUp({ email, password });
    // Generic on purpose: don't reveal whether an email already has an account.
    if (error) return { error: "Couldn't create an account with these details. If you already have one, sign in.", email };
    if (!data.session) return { message: "Check your email to confirm your account, then sign in.", email };
  }

  redirect("/tasks");
}

export async function signOut() {
  const supabase = await createClient();
  await supabase.auth.signOut();
  redirect("/login");
}
import type { Metadata } from "next";
import { CheckSquareIcon } from "@/components/icons";
import { LoginForm } from "@/components/LoginForm";

export const metadata: Metadata = { title: "Sign in · Tasks" };

export default function LoginPage() {
  return (
    <section className="auth-card">
      <span className="brand-mark brand-mark-lg" aria-hidden="true">
        <CheckSquareIcon />
      </span>
      <h1>Sign in to Tasks</h1>
      <p className="muted">Sign in, or create an account with an email and password.</p>
      <LoginForm />
    </section>
  );
}
"use client";

import { useActionState } from "react";
import { authenticate, type AuthFormState } from "@/app/login/actions";

const initialState: AuthFormState = {};

export function LoginForm() {
  const [state, formAction, pending] = useActionState(authenticate, initialState);

  return (
    <form action={formAction} className="stack">
      <label>
        Email
        <input
          name="email"
          type="email"
          autoComplete="email"
          placeholder="you@example.com"
          required
          defaultValue={state.email}
        />
      </label>
      <label>
        Password
        <input name="password" type="password" autoComplete="current-password" placeholder="At least 8 characters" required />
      </label>
      {state.error ? (
        <p role="alert" className="error banner">
          {state.error}
        </p>
      ) : null}
      {state.message ? (
        <p role="status" className="notice">
          {state.message}
        </p>
      ) : null}
      <div className="auth-actions">
        <button type="submit" name="intent" value="signin" disabled={pending}>
          {pending ? "Please wait…" : "Sign in"}
        </button>
        <button type="submit" name="intent" value="signup" className="secondary" disabled={pending}>
          Create account
        </button>
      </div>
    </form>
  );
}
import "server-only";
import { redirect } from "next/navigation";
import { cache } from "react";
import { createClient } from "@/lib/supabase/server";

/** The current user (validated with the auth server), or null. Deduplicated per request. */
export const getCurrentUser = cache(async () => {
  const supabase = await createClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) return { supabase, user: null };
  return { supabase, user: { id: data.user.id, email: data.user.email ?? "" } };
});

/** Use in every Server Action and data read: redirects to /login when signed out. */
export async function requireUser() {
  const { supabase, user } = await getCurrentUser();
  if (!user) redirect("/login");
  return { supabase, user };
}
import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { supabaseEnv } from "@/lib/supabase/env";

const PUBLIC_PATHS = ["/login"];

/**
 * Refreshes the Supabase session cookie and makes an optimistic redirect.
 * This is not the authorisation check: requireUser() and RLS are.
 */
export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request });
  const { url, publishableKey } = supabaseEnv();

  const supabase = createServerClient(url, publishableKey, {
    cookies: {
      getAll() {
        return request.cookies.getAll();
      },
      setAll(cookiesToSet, headers) {
        for (const { name, value } of cookiesToSet) request.cookies.set(name, value);
        response = NextResponse.next({ request });
        for (const { name, value, options } of cookiesToSet) response.cookies.set(name, value, options);
        for (const [key, value] of Object.entries(headers ?? {})) response.headers.set(key, value);
      },
    },
  });

  // getClaims validates the JWT and refreshes an expired session (writing new cookies above).
  const { data } = await supabase.auth.getClaims();
  const signedIn = Boolean(data?.claims);
  const { pathname } = request.nextUrl;
  const isPublic = PUBLIC_PATHS.some((p) => pathname === p || pathname.startsWith(`${p}/`));

  if (!signedIn && !isPublic) return redirectKeepingCookies(request, response, "/login");

  if (signedIn && isPublic) {
    // getClaims only checks the JWT locally, so a revoked session still looks signed in until
    // the token expires. requireUser() asks the auth server and would send /tasks straight back
    // here, looping. Confirm with the auth server before leaving /login (only /login pays this),
    // and clear the stale session if it fails.
    const { data: userData, error } = await supabase.auth.getUser();
    if (!error && userData.user) return redirectKeepingCookies(request, response, "/tasks");
    await supabase.auth.signOut({ scope: "local" });
  }
  return response;
}

function redirectKeepingCookies(request: NextRequest, from: NextResponse, pathname: string) {
  const target = request.nextUrl.clone();
  target.pathname = pathname;
  target.search = "";
  const redirect = NextResponse.redirect(target);
  for (const cookie of from.cookies.getAll()) redirect.cookies.set(cookie);
  return redirect;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)"],
};
import "server-only";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { connection } from "next/server";
import type { Database } from "./database.types";
import { supabaseEnv } from "./env";

/**
 * Supabase client acting as the signed-in user (publishable key + session cookies).
 * RLS is the security boundary; the app never uses the secret/service-role key.
 * Create one per request.
 */
export async function createClient() {
  // Session reads and token checks use the current time, so always run them at request time
  // (Cache Components would otherwise flag supabase-js's Date.now() during prerendering).
  await connection();
  const cookieStore = await cookies();
  const { url, publishableKey } = supabaseEnv();

  return createServerClient<Database>(url, publishableKey, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          for (const { name, value, options } of cookiesToSet) cookieStore.set(name, value, options);
        } catch {
          // Server Components can't set cookies. The Proxy refreshes the session instead.
        }
      },
    },
  });
}
export function supabaseEnv() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const publishableKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  if (!url || !publishableKey) {
    throw new Error(
      "Missing NEXT_PUBLIC_SUPABASE_URL or NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY. Copy .env.example to .env.local.",
    );
  }
  return { url, publishableKey };
}
