"use server";

import { headers } from "next/headers";
import { createClient } from "@/lib/supabase/server";
import { normaliseEmail, validateEmail } from "@/lib/credentials";

export type SignupState = { error?: string; sentTo?: string; email?: string };

/**
 * Step 1 of account creation: email the user a verification link. The account gets a password
 * only after they follow the link (see /auth/confirm and /set-password).
 */
export async function requestSignup(_prev: SignupState, formData: FormData): Promise<SignupState> {
  const email = normaliseEmail(formData.get("email"));
  const invalid = validateEmail(email);
  if (invalid) return { error: invalid, email };

  // Server Action POSTs always carry Origin, and Next.js rejects ones that don't match the host.
  // Supabase Auth also checks the redirect against its allow-list.
  const origin = (await headers()).get("origin");
  if (!origin) return { error: "Couldn't send the email. Reload the page and try again.", email };

  const supabase = await createClient();
  const { error } = await supabase.auth.signInWithOtp({
    email,
    options: {
      shouldCreateUser: true,
      emailRedirectTo: `${origin}/auth/confirm`,
      // Only applied when the user is created, so existing accounts are untouched.
      data: { needs_password: true },
    },
  });

  if (error) {
    if (error.status === 429) return { error: "Too many emails requested. Wait a minute and try again.", email };
    return { error: "Couldn't send the email. Try again in a moment.", email };
  }

  // Same response whether or not the email already has an account, so this can't be used to
  // find out who has signed up. Existing users get a sign-in link instead.
  return { sentTo: email, email };
}

import { NextResponse, type NextRequest } from "next/server";
import type { User } from "@supabase/supabase-js";
import { parseEmailLinkType } from "@/lib/credentials";
import { createClient } from "@/lib/supabase/server";

/**
 * Landing page for the link in the sign-up email. Exchanges the link for a session, then sends
 * new users on to choose a password.
 *
 * Accepts both link shapes Supabase can send:
 * - `token_hash` + `type` (our email templates): works even if the link is opened in another browser.
 * - `code` (the default hosted template, PKCE): needs the browser that requested the email.
 */
export async function GET(request: NextRequest) {
  const { searchParams } = request.nextUrl;
  const tokenHash = searchParams.get("token_hash");
  const type = parseEmailLinkType(searchParams.get("type"));
  const code = searchParams.get("code");

  const supabase = await createClient();
  let user: User | null = null;

  if (tokenHash && type) {
    const { data, error } = await supabase.auth.verifyOtp({ token_hash: tokenHash, type });
    if (!error) user = data.user;
  } else if (code) {
    const { data, error } = await supabase.auth.exchangeCodeForSession(code);
    if (!error) user = data.user;
  }

  if (!user) return redirectTo(request, "/signup?error=link");
  return redirectTo(request, user.user_metadata?.needs_password === true ? "/set-password" : "/tasks");
}

function redirectTo(request: NextRequest, path: string) {
  return NextResponse.redirect(new URL(path, request.nextUrl.origin));
}

"use server";

import { redirect } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { validateNewPassword } from "@/lib/credentials";

export type SetPasswordState = { error?: string };

/** Final step of account creation: save the password, then send the user to sign in with it. */
export async function setPassword(_prev: SetPasswordState, formData: FormData): Promise<SetPasswordState> {
  const password = String(formData.get("password") ?? "");
  const confirmation = String(formData.get("confirmPassword") ?? "");

  const invalid = validateNewPassword(password, confirmation);
  if (invalid) return { error: invalid };

  const { supabase } = await requireUser();
  const { error } = await supabase.auth.updateUser({ password, data: { needs_password: false } });
  if (error) {
    if (error.code === "weak_password") return { error: "That password is too easy to guess. Choose another." };
    return { error: "Couldn't save your password. Try again." };
  }

  // Sign in fresh with the new password, so the user knows it works before they need it.
  await supabase.auth.signOut();
  redirect("/login?status=password-set");
}

